declare global {
  interface Window {
    // Prevent duplicate listeners/intervals if the script is injected again.
    __autoScrollExtensionInitialized?: boolean;
  }
}

type ScrollAction = "start" | "pause" | "resume" | "stop" | "status";
type ScrollDirection = "up" | "left" | "down" | "right";

type ScrollMessage = {
  action?: ScrollAction;
  speed?: number;
  direction?: ScrollDirection;
  loop?: boolean;
  reset?: boolean;
  jumpScroll?: boolean;
  slowMode?: boolean;
  lineDelayMs?: number;
};

type ScrollRuntimeState = "idle" | "running" | "paused";

type ScrollStatus = {
  isRunning: boolean;
  isPaused: boolean;
  speed: number;
};

type ScrollSchedulerMode = "smooth" | "jump" | null;

if (!window.__autoScrollExtensionInitialized) {
  window.__autoScrollExtensionInitialized = true;

  const DEFAULT_SCROLL_STEP = 3;
  const DEFAULT_SCROLL_DIRECTION: ScrollDirection = "down";
  const DEFAULT_JUMP_SCROLL = false;
  const DEFAULT_SLOW_MODE = false;
  const DEFAULT_LINE_DELAY_MS = 220;
  const MAX_SCROLL_STEP = 20;
  const NORMAL_MIN_SCROLL_STEP = 1;
  const SLOW_MODE_MIN_SCROLL_STEP = 0.1;

  let scrollTimer: number | null = null;
  let scrollSchedulerMode: ScrollSchedulerMode = null;
  let smoothLastFrameTime: number | null = null;
  let scrollStep = DEFAULT_SCROLL_STEP;
  let scrollDirection: ScrollDirection = DEFAULT_SCROLL_DIRECTION;
  let jumpScrollEnabled = DEFAULT_JUMP_SCROLL;
  let slowModeEnabled = DEFAULT_SLOW_MODE;
  let lineDelayMs = DEFAULT_LINE_DELAY_MS;
  // When true, reaching a boundary rewinds to the start and continues.
  let loopAtEnd = false;
  let hasStarted = false;
  let isPaused = false;

  function getRuntimeState(): ScrollRuntimeState {
    if (scrollTimer !== null) {
      return "running";
    }

    if (isPaused) {
      return "paused";
    }

    return "idle";
  }

  function reportBadgeState(): void {
    void chrome.runtime
      .sendMessage({
        type: "badge-status",
        state: getRuntimeState(),
        speed: scrollStep
      })
      .catch(() => {
        // Ignore failures when the extension context is unavailable.
      });
  }

  function getMinScrollStep(): number {
    return slowModeEnabled ? SLOW_MODE_MIN_SCROLL_STEP : NORMAL_MIN_SCROLL_STEP;
  }

  function normalizeScrollStep(value: number): number {
    const clamped = Math.min(MAX_SCROLL_STEP, Math.max(getMinScrollStep(), value));

    if (!slowModeEnabled) {
      return Math.round(clamped);
    }

    return Math.round(clamped * 10) / 10;
  }

  function setScrollSpeed(speed: number | undefined): void {
    if (typeof speed !== "number" || !Number.isFinite(speed)) {
      return;
    }

    scrollStep = normalizeScrollStep(speed);

    if (scrollTimer !== null) {
      reportBadgeState();
    }
  }

  function setSlowModeSetting(enabled: boolean | undefined): void {
    if (typeof enabled !== "boolean") {
      return;
    }

    slowModeEnabled = enabled;
    scrollStep = normalizeScrollStep(scrollStep);

    if (scrollTimer !== null) {
      reportBadgeState();
    }
  }

  function setScrollDirection(direction: ScrollDirection | undefined): void {
    if (direction !== "up" && direction !== "left" && direction !== "down" && direction !== "right") {
      return;
    }

    scrollDirection = direction;
  }

  function setLoopSetting(loop: boolean | undefined): void {
    if (typeof loop === "boolean") {
      loopAtEnd = loop;
    }
  }

  function clampLineDelay(delay: number): number {
    return Math.min(1200, Math.max(60, Math.round(delay / 20) * 20));
  }

  function setJumpScrollSetting(enabled: boolean | undefined): void {
    if (typeof enabled !== "boolean") {
      return;
    }

    if (jumpScrollEnabled === enabled) {
      return;
    }

    jumpScrollEnabled = enabled;

    if (scrollTimer !== null) {
      restartScrollTimer();
    }
  }

  function setLineDelay(delay: number | undefined): void {
    if (typeof delay !== "number" || !Number.isFinite(delay)) {
      return;
    }

    const nextDelay = clampLineDelay(delay);

    if (lineDelayMs === nextDelay) {
      return;
    }

    lineDelayMs = nextDelay;

    if (scrollTimer !== null && jumpScrollEnabled) {
      restartScrollTimer();
    }
  }

  function resetToStart(): void {
    // Rewind to the logical start for the current direction.
    if (scrollDirection === "up") {
      const maxVerticalScroll = Math.max(0, document.documentElement.scrollHeight - window.innerHeight);
      window.scrollTo(window.scrollX, maxVerticalScroll);
    } else if (scrollDirection === "left") {
      window.scrollTo(window.scrollX + window.innerWidth, window.scrollY);
    } else if (scrollDirection === "right") {
      window.scrollTo(0, window.scrollY);
    } else {
      window.scrollTo(window.scrollX, 0);
    }
  }

  function isAtPageBottom(): boolean {
    const scrollBottom = window.scrollY + window.innerHeight;
    const pageHeight = document.documentElement.scrollHeight;
    return scrollBottom >= pageHeight - 2;
  }

  function isAtPageTop(): boolean {
    return window.scrollY <= 0;
  }

  function isAtHorizontalStart(): boolean {
    return window.scrollX <= 0;
  }

  function isAtHorizontalEnd(): boolean {
    const scrollRight = window.scrollX + window.innerWidth;
    const pageWidth = document.documentElement.scrollWidth;
    return scrollRight >= pageWidth - 2;
  }

  function isAtScrollBoundary(): boolean {
    // Use direction-specific boundary checks so one timer supports all directions.
    if (scrollDirection === "up") {
      return isAtPageTop();
    }

    if (scrollDirection === "left") {
      return isAtHorizontalStart();
    }

    if (scrollDirection === "right") {
      return isAtHorizontalEnd();
    }

    return isAtPageBottom();
  }

  function getScrollDelta(): { x: number; y: number } {
    if (scrollDirection === "up") {
      return { x: 0, y: -scrollStep };
    }

    if (scrollDirection === "left") {
      return { x: -scrollStep, y: 0 };
    }

    if (scrollDirection === "right") {
      return { x: scrollStep, y: 0 };
    }

    return { x: 0, y: scrollStep };
  }

  function scrollByDistance(distance: number): void {
    if (scrollDirection === "up") {
      window.scrollBy(0, -distance);
      return;
    }

    if (scrollDirection === "left") {
      window.scrollBy(-distance, 0);
      return;
    }

    if (scrollDirection === "right") {
      window.scrollBy(distance, 0);
      return;
    }

    window.scrollBy(0, distance);
  }

  function getJumpDistance(): number {
    const computedLineHeight = Number.parseFloat(window.getComputedStyle(document.body).lineHeight);

    if (Number.isFinite(computedLineHeight) && computedLineHeight > 0) {
      return Math.max(8, Math.min(120, Math.round(computedLineHeight)));
    }

    return 24;
  }

  function performScrollTick(): void {
    if (isAtScrollBoundary()) {
      if (loopAtEnd) {
        // Jump back immediately; next tick continues scrolling.
        resetToStart();
      } else {
        stopAutoScroll();
      }
      return;
    }

    if (jumpScrollEnabled) {
      const jumpDistance = getJumpDistance();
      const jumpMultiplier = slowModeEnabled
        ? Math.max(SLOW_MODE_MIN_SCROLL_STEP, scrollStep / 3)
        : Math.max(1, Math.round(scrollStep / 3));
      scrollByDistance(jumpDistance * jumpMultiplier);
      return;
    }

    const delta = getScrollDelta();
    window.scrollBy(delta.x, delta.y);
  }

  function getTickIntervalMs(): number {
    return jumpScrollEnabled ? lineDelayMs : 16;
  }

  function stopScrollScheduler(): void {
    if (scrollTimer === null) {
      scrollSchedulerMode = null;
      smoothLastFrameTime = null;
      return;
    }

    if (scrollSchedulerMode === "smooth") {
      window.cancelAnimationFrame(scrollTimer);
    } else {
      window.clearInterval(scrollTimer);
    }

    scrollTimer = null;
    scrollSchedulerMode = null;
    smoothLastFrameTime = null;
  }

  function runSmoothFrame(timestamp: number): void {
    if (scrollTimer === null || scrollSchedulerMode !== "smooth") {
      return;
    }

    if (isAtScrollBoundary()) {
      if (loopAtEnd) {
        resetToStart();
      } else {
        stopAutoScroll();
        return;
      }
    }

    if (smoothLastFrameTime === null) {
      smoothLastFrameTime = timestamp;
    }

    const elapsedMs = Math.max(0, timestamp - smoothLastFrameTime);
    smoothLastFrameTime = timestamp;

    // Keep the historical baseline (~scrollStep px per 16ms) but smooth per-frame.
    const pixelsPerSecond = scrollStep * 62.5;
    const nextDistance = (pixelsPerSecond * elapsedMs) / 1000;

    if (nextDistance > 0) {
      // Use fractional distances to avoid stutter at slow-mo speeds.
      scrollByDistance(nextDistance);
    }

    scrollTimer = window.requestAnimationFrame(runSmoothFrame);
  }

  function startSmoothScheduler(): void {
    stopScrollScheduler();
    scrollSchedulerMode = "smooth";
    smoothLastFrameTime = null;
    scrollTimer = window.requestAnimationFrame(runSmoothFrame);
  }

  function startJumpScheduler(): void {
    stopScrollScheduler();
    scrollSchedulerMode = "jump";
    scrollTimer = window.setInterval(() => {
      performScrollTick();
    }, getTickIntervalMs());
  }

  function restartScrollTimer(): void {
    if (jumpScrollEnabled) {
      startJumpScheduler();
      return;
    }

    startSmoothScheduler();
  }

  function startAutoScroll(): void {
    if (scrollTimer !== null) {
      return;
    }

    hasStarted = true;
    isPaused = false;

    restartScrollTimer();

    reportBadgeState();
  }

  function stopAutoScroll(): void {
    if (scrollTimer === null) {
      hasStarted = false;
      isPaused = false;
      return;
    }

    stopScrollScheduler();
    hasStarted = false;
    isPaused = false;
    reportBadgeState();
  }

  function resetScrollSession(): void {
    // Hard reset restores non-persistent runtime state for speed and direction.
    scrollStep = DEFAULT_SCROLL_STEP;
    scrollDirection = DEFAULT_SCROLL_DIRECTION;
    jumpScrollEnabled = DEFAULT_JUMP_SCROLL;
    slowModeEnabled = DEFAULT_SLOW_MODE;
    lineDelayMs = DEFAULT_LINE_DELAY_MS;
  }

  function pauseAutoScroll(): void {
    if (scrollTimer === null) {
      return;
    }

    stopScrollScheduler();

    if (hasStarted) {
      isPaused = true;
    }

    reportBadgeState();
  }

  function resumeAutoScroll(): void {
    if (!hasStarted || !isPaused || scrollTimer !== null) {
      return;
    }

    startAutoScroll();
    reportBadgeState();
  }

  function getScrollStatus(): ScrollStatus {
    return {
      isRunning: scrollTimer !== null,
      isPaused,
      speed: scrollStep
    };
  }

  chrome.runtime.onMessage.addListener((message: ScrollMessage, _sender, sendResponse) => {
    if (!message.action) {
      return;
    }

    if (message.action === "status") {
      sendResponse(getScrollStatus());
      return;
    }

    // Each action can also refresh runtime settings.
    setSlowModeSetting(message.slowMode);
    setScrollSpeed(message.speed);
    setScrollDirection(message.direction);
    setLoopSetting(message.loop);
    setJumpScrollSetting(message.jumpScroll);
    setLineDelay(message.lineDelayMs);

    if (message.action === "start") {
      startAutoScroll();
    }

    if (message.action === "stop") {
      stopAutoScroll();

      if (message.reset) {
        resetScrollSession();
      }
    }

    if (message.action === "pause") {
      pauseAutoScroll();
    }

    if (message.action === "resume") {
      resumeAutoScroll();
    }
  });

  reportBadgeState();
}

export {};
